import ast
src = open(sol.__file__).read()
tree = ast.parse(src)
defs = [n for n in ast.walk(tree) if isinstance(n, (ast.FunctionDef, ast.AsyncFunctionDef))]
names = set(d.name for d in defs)
graph = {}
for d in defs:
    calls = set()
    for x in ast.walk(d):
        if isinstance(x, ast.Call) and isinstance(x.func, ast.Name) and x.func.id in names:
            calls.add(x.func.id)
    graph.setdefault(d.name, set()).update(calls)
cyclic = False
for start in graph:
    seen = set()
    stack = [start]
    while stack:
        cur = stack.pop()
        for nxt in graph.get(cur, ()):
            if nxt == start:
                cyclic = True
            if nxt not in seen:
                seen.add(nxt)
                stack.append(nxt)
loops = any(isinstance(n, (ast.For, ast.AsyncFor, ast.While)) for n in ast.walk(tree))
comps = any(isinstance(n, (ast.ListComp, ast.SetComp, ast.DictComp, ast.GeneratorExp))
            for n in ast.walk(tree))
imports = any(isinstance(n, (ast.Import, ast.ImportFrom)) for n in ast.walk(tree))
result = (cyclic, loops, comps, imports)

